{"path":"src/java_module.java","content":"// Метод ищет активного пользователя по логину.
// Возвращает Optional, чтобы явно показать: пользователь может отсутствовать,
// а вызывающий код обязан обработать этот случай (например, через isPresent/getOrElse).
public Optional<User> findActive(String login) {
    // Берём поток из коллекции всех пользователей.
    return users.stream()
        // Первый фильтр: совпадение логина без учёта регистра.
        // Используем equalsIgnoreCase, потому что пользователи часто вводят
        // логин с разными регистрами букв, а учётная запись одна.
        .filter(u -> u.getLogin().equalsIgnoreCase(login))
        // Второй фильтр: пользователь должен быть активным.
        // Активность определяется двумя условиями:
        //  1) аккаунт не заблокирован (!u.isBlocked());
        //  2) срок действия ещё не истёк — дата окончания в будущем
        //     относительно текущего момента (isAfter(Instant.now())).
        // Объединяем условия через &&: оба должны выполняться одновременно.
        .filter(u -> !u.isBlocked() && u.getExpiresAt().isAfter(Instant.now()))
        // Останавливаемся на первом подходящем элементе.
        // findFirst возвращает Optional.empty(), если ничего не найдено,
        // поэтому исключение NoSuchElementException здесь не возникнет.
        .findFirst();
}
"}

{"path":"src/csharp_module.cs","content":"// Метод реализует повторные попытки выполнения асинхронного действия
// с экспоненциальной задержкой между ними (backoff).
public async Task<int> RetryAsync(Func<Task<int>> action, int attempts)
{
    // Перебираем все доступные попытки: от 0 до attempts - 1.
    for (var i = 0; i < attempts; i++)
    {
        try
        {
            // Выполняем действие и сразу возвращаем его результат.
            // Если всё прошло успешно — цикл завершается здесь.
            return await action();
        }
        catch (HttpRequestException) when (i < attempts - 1)
        {
            // Перехватываем только сетевые ошибки (HttpRequestException).
            // Фильтр "when (i < attempts - 1)" гарантирует, что на последней
            // попытке мы НЕ глотаем исключение, а даём ему вылететь наружу —
            // так вызывающий код узнаёт, что все попытки исчерпаны.
            //
            // Задержка растёт экспоненциально: 200мс, 400мс, 800мс и т.д.
            // Это классический exponential backoff: он даёт серверу время
            // "остыть" и при этом не ждёт слишком долго в худшем случае.
            await Task.Delay(TimeSpan.FromMilliseconds(200 * Math.Pow(2, i)));
        }
    }

    // Теоретически недостижимая строка: либо метод уже вернул результат,
    // либо на последней попытке исключение было проброшено через фильтр "when".
    // Оставляем бросок, чтобы компилятор был уверен, что метод всегда
    // завершается определённо (возврат значения или исключение).
    throw new InvalidOperationException("unreachable");
}
"}

{"path":"src/go_module.go","content":"// Функция worker — обработчик (воркер) в пуле, который постоянно читает
// задачи из канала jobs и отправляет результаты в канал results.
//
// Параметры:
//   - jobs    — входной канал задач; воркер работает, пока канал открыт,
//     поэтому цикл range сам завершится после close(jobs).
//   - results — выходной канал для готовых результатов.
//   - wg      — указатель на WaitGroup, чтобы главный горутин-менеджер мог
//     дождаться завершения всех воркеров.
func worker(jobs <-chan Job, results chan<- Result, wg *sync.WaitGroup) {
	// defer гарантирует, что счётчик WaitGroup будет уменьшен даже при панике,
	// иначе main() зависнет в ожидании wg.Wait().
	defer wg.Done()

	// Цикл range по каналу блокируется, пока нет новой задачи, и выходит
	// автоматически, когда канал закрыт. Это стандартный идиоматичный способ
	// реализовать "бесконечный" обработчик с корректным завершением.
	for j := range jobs {
		// process выполняет фактическую работу над задачей.
		r, err := process(j)
		if err != nil {
			// При ошибке логируем её вместе с ID задачи (для отладки) и
			// пропускаем задачу, не прерывая работу воркера: одна плохая
			// задача не должна останавливать весь конвейер.
			log.Printf("job %d: %v", j.ID, err)
			continue
		}
		// Отправляем результат в общий канал. Если буфер results переполнен,
		// это естественная точка синхронизации: воркер подождёт, пока кто-то
		// заберёт результат (backpressure).
		results <- r
	}
}
"}

{"path":"src/typescript_module.ts","content":"/**
 * Функция debounce (дебаунс) — классический паттерн для «гашения» частых вызовов.
 *
 * Что делает:
 *  Возвращает обёртку над переданной функцией `fn`, которая откладывает её
 *  выполнение на `ms` миллисекунд. Если в течение этого времени функция
 *  вызывают снова, предыдущий таймер сбрасывается и отсчёт начинается заново.
 *  В итоге `fn` сработает только один раз — через `ms` мс после ПОСЛЕДНЕГО
 *  вызова обёртки.
 *
 * Почему именно так:
 *  - Тип `T extends (...a: any[]) => void` позволяет принять функцию с любой
 *    сигнатурой аргументов, сохранив при этом точную типизацию:
 *      * `Parameters<T>` — извлекает кортеж типов аргументов исходной функции,
 *        поэтому обёртка принимает ровно те же аргументы;
 *      * `ReturnType<typeof setTimeout>` — корректный тип идентификатора таймера
 *        как в Node.js (число), так и в браузере (объект Timeout). Это важно,
 *        потому что без него компилятор ругался бы на несовместимость типов
 *        `clearTimeout`/`setTimeout` между окружениями.
 *  - Переменная `t` хранит идентификатор текущего таймера. Проверка `if (t)`
 *    нужна, чтобы не вызывать `clearTimeout(undefined)` при первом вызове.
 *  - Стрелочная функция замыкает `t` и `fn`, создавая «приватное» состояние
 *    для каждого отдельного экземпляра дебаунса (каждый вызов `debounce(...)`
 *    получает собственный таймер).
 *
 * Пример использования:
 *   const onResize = debounce(() => console.log('окно изменилось'), 300);
 *   window.addEventListener('resize', onResize);
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Идентификатор активного таймера. `undefined` означает, что таймер сейчас
  // не установлен (первый вызов или уже отработавший таймер).
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем обёртку с той же сигнатурой аргументов, что и исходная функция.
  return (...args: Parameters<T>) => {
    // Если есть незавершённый таймер — отменяем его, чтобы сбросить отсчёт.
    if (t) clearTimeout(t);
    // Ставим новый таймер: `fn` выполнится через `ms` мс с последними
    // переданными аргументами (они захвачены замыканием).
    t = setTimeout(() => fn(...args), ms);
  };
}
"}

{"path":"src/rust_module.rs","content":"use std::collections::HashMap;

/// Разбирает строку в формате "ключ1=значение1;ключ2=значение2" в словарь.
///
/// Формат входной строки: пары «ключ=значение», разделённые точкой с запятой.
/// Пример: `"Name=Alice; Age=30"` -> `{"name": "Alice", "age": "30"}`.
///
/// Правила обработки:
/// - Ключ приводится к нижнему регистру и очищается от пробелов по краям,
///   чтобы запросы были нечувствительны к регистру и лишним пробелам.
/// - Значение только обрезается по краям (регистр сохраняется как есть).
/// - Части без символа `=` (например, хвост после последнего `;`)
///   молча пропускаются — это делает парсер устойчивым к «мусору» на входе.
pub fn parse_kv(s: &str) -> HashMap<String, String> {
    s.split(';') // 1) Режем строку на части по разделителю ';'.
        .filter_map(|p| p.split_once('=')) // 2) Оставляем только те части, где есть '=';
            // split_once возвращает Option<&(k, v)> — filter_map аккуратно
            // выбрасывает некорректные фрагменты вместо паники.
        .map(|(k, v)| (k.trim().to_lowercase(), v.trim().to_string())) // 3) Нормализуем ключ
            // (trim + lower) и значение (только trim). to_lowercase/to_string
            // создают новые String'и, потому что результат должен жить дольше
            // исходного среза s.
        .collect() // 4) Собираем итератор пар в HashMap.
}
"}
